pub fn fill_Vec(p: &mut Vec) {
    p.x = rg();
    p.y = rg();
    p.z = rg();
}
pub fn hash_Vec(p: &Vec) {
    hn("p->x");
    hm(p.x.to_bits());
    hn("p->y");
    hm(p.y.to_bits());
    hn("p->z");
    hm(p.z.to_bits());
}
